impl Solution {
    pub fn count_routes(locations: Vec<i32>, start: i32, finish: i32, fuel: i32) -> i32 {
        let n = locations.len();
        let start_index = start as usize;
        let finish_index = finish as usize;
        let mut dp = vec![vec![0; (fuel + 1) as usize]; n];

        dp[start_index][fuel as usize] = 1;

        for f in 0..=fuel {
            for i in 0..n {
                if dp[i][f as usize] == 0 {
                    continue;
                }

                for j in 0..n {
                    if i == j {
                        continue;
                    }

                    let cost = (locations[i] - locations[j]).abs() as i32;

                    if cost <= f {
                        dp[j][(f - cost) as usize] = (dp[j][(f - cost) as usize] + dp[i][f as usize]) % 1_000_000_007;
                    }
                }
            }
        }

        let mut result = 0;
        for f in 0..=fuel {
            result = (result + dp[finish_index][f as usize]) % 1_000_000_007;
        }

        result
    }
}

